preConditionHook:
// THE WEDGE / THREE-PUSH REVERSAL ENTRY. The pattern was complete as of the
// PRIOR bar and this bar reverses out of it: after three pushes DOWN, the
// close is above the prior bar's high (long); after three pushes UP, below the
// prior bar's low (short). Signal-bar close, next-bar open: the standing
// convention.
//
// The with-trend reading (a wedge pullback in a bull trend) and the
// countertrend reading (a wedge reversal at a top) fire on the SAME bars --
// the split is context supplied by other panes, not a different trigger -- so
// they are one rule. No signal-bar quality gate: Brooks takes the entry even
// when the signal bar is a bear trend bar, and any body or tail test belongs
// to its own bar-anatomy pane.
//
// patDnPrev / patUpPrev MIRROR the pattern flag one bar back rather than
// reading a history of it: they are assigned at the top of the hook, before
// the scan overwrites the flag, so they hold the previous evaluated bar's
// value and start false through warm-up -- the arrangement BarRangeAboveStd
// uses for an EL variable's own history, and what the twin's variables do
// natively.
//
// The pivot scan is ThreePushPattern's, inlined: rules in this corpus never
// reference each other, and the register lists SwingLow's Occurrence 3+ as
// unmeasured, so the third push is found by hand. Measured behaviour
// reproduced (EL_Swing_Probe.txt / el_swing_output1.txt, @ES 60 min): the
// pivot bar is AT OR ABOVE the swingStrength OLDER bars and STRICTLY ABOVE the
// swingStrength NEWER bars -- bars-ago indexing, so the newer bars are the
// SMALLER k and take el_gt / el_lt while the older take el_ge / el_le;
// confirmation lag exactly swingStrength bars; candidate offsets
// swingStrength .. lookbackBars - 1, the neighbourhood reaching swingStrength
// bars past the window, so the deepest bar touched is
// lookbackBars - 1 + swingStrength; newest-first recording reproduces
// Occurrence 1, 2, 3; the -1 sentinel is initialised and gated on the counts.
// No early break, matching the twin: Break is not a registered EL word.
// Scratch below is declared in localVariables, not at hook scope: the
// generator only prefixes declared locals, so a hook-scope declaration
// is a redefinition when this rule is placed twice in one strategy.
// Every one is fully assigned each bar before it is read.
pivStrength = (int)swingStrength;
pivWindow = (int)lookbackBars;
patUpPrev = patUp;
patDnPrev = patDn;
nHiPiv = 0;
nLoPiv = 0;
hiPx1 = -1.0;
hiPx2 = -1.0;
hiPx3 = -1.0;
loPx1 = -1.0;
loPx2 = -1.0;
loPx3 = -1.0;
for (int j = pivStrength; j <= pivWindow - 1; ++j) {
    bool okHi = true;
    bool okLo = true;
    for (int k = j - pivStrength; k < j; ++k) {
        if (!el_gt(high[j], high[k])) okHi = false;
        if (!el_lt(low[j], low[k])) okLo = false;
    }
    for (int k = j + 1; k <= j + pivStrength; ++k) {
        if (!el_ge(high[j], high[k])) okHi = false;
        if (!el_le(low[j], low[k])) okLo = false;
    }
    if (okHi && nHiPiv < 3) {
        nHiPiv = nHiPiv + 1;
        if (nHiPiv == 1) hiPx1 = high[j];
        if (nHiPiv == 2) hiPx2 = high[j];
        if (nHiPiv == 3) hiPx3 = high[j];
    }
    if (okLo && nLoPiv < 3) {
        nLoPiv = nLoPiv + 1;
        if (nLoPiv == 1) loPx1 = low[j];
        if (nLoPiv == 2) loPx2 = low[j];
        if (nLoPiv == 3) loPx3 = low[j];
    }
}
patUp = (nHiPiv == 3) && el_gt(hiPx1, hiPx2) && el_gt(hiPx2, hiPx3);
patDn = (nLoPiv == 3) && el_lt(loPx1, loPx2) && el_lt(loPx2, loPx3);
